","import React, { useState, useEffect } from "react";

/* ─── Types ─── */
interface FieldVal {
 display_value: string;
 value: string;
}
type Rec = Record<string, FieldVal>;

/* ─── API Helper ─── */
const headers = (): HeadersInit => ({
 Accept: "application/json",
 "X-UserToken": (window as any).g_ck,
});

async function fetchTable(table: string, fields: string, query?: string): Promise<Rec[]> {
 let url = `/api/now/table/${table}?sysparm_display_value=all&sysparm_fields=${fields}`;
 if (query) url += `&sysparm_query=${encodeURIComponent(query)}`;
 const res = await fetch(url, { headers: headers() });
 const data = await res.json();
 return data.result || [];
}

const val = (f?: FieldVal) => f?.value || "";
const dv = (f?: FieldVal) => f?.display_value || "";
const num = (f?: FieldVal) => parseInt(f?.value || "0", 10) || 0;

/* ─── Sub-Components ─── */
function KpiCard({ label, value, icon, accent }: { label: string; value: number | string; icon: string; accent?: string }) {
 return (
 <div className={`ops-kpi-card${accent ? ` ops-kpi-card--${accent}` : ""}`}>
 <div className="ops-kpi-icon">{icon}</div>
 <div className="ops-kpi-value">{value}</div>
 <div className="ops-kpi-label">{label}</div>
 </div>
 );
}

function ResourceBar({ label, count, total, color }: { label: string; count: number; total: number; color: string }) {
 const pct = total > 0 ? (count / total) * 100 : 0;
 return (
 <div className="ops-resource-row">
 <span className="ops-resource-label">{label}</span>
 <div className="ops-resource-bar">
 <div className="ops-resource-fill" style={{ width: `${pct}%`, backgroundColor: color }} />
 </div>
 <span className="ops-resource-count">{count}</span>
 </div>
 );
}

function AlertGroup({ label, severity, alerts }: { label: string; severity: string; alerts: Rec[] }) {
 return (
 <div className={`ops-alert-group ops-alert-group--${severity}`}>
 <div className="ops-alert-header">
 <span className={`ops-severity-dot ops-severity-dot--${severity}`} />
 <strong>{label}</strong>
 <span className="ops-alert-count">{alerts.length}</span>
 </div>
 {alerts.map((a, i) => (
 <div key={i} className="ops-alert-item">
 <span className="ops-alert-number">{dv(a.number)}</span>
 <span className="ops-alert-type">{dv(a.alert_type)}</span>
 <span className="ops-alert-msg">{dv(a.alert_message)}</span>
 <span className="ops-alert-material">{dv(a.material_product)}</span>
 </div>
 ))}
 </div>
 );
}

function Placeholder({ icon, text }: { icon: string; text: string }) {
 return (
 <div className="ops-placeholder">
 <span className="ops-placeholder-icon">{icon}</span>
 <p>{text}</p>
 </div>
 );
}

/* ─── Main Dashboard ─── */
export default function DashboardApp() {
 const [orders, setOrders] = useState<Rec[]>([]);
 const [prodOrders, setProdOrders] = useState<Rec[]>([]);
 const [resources, setResources] = useState<Rec[]>([]);
 const [stock, setStock] = useState<Rec[]>([]);
 const [alerts, setAlerts] = useState<Rec[]>([]);
 const [loading, setLoading] = useState(true);

 useEffect(() => {
 loadAll();
 }, []);

 async function loadAll() {
 try {
 const [o, p, r, s, a] = await Promise.all([
 fetchTable(
 "x_2056099_indust_0_cust_order",
 "number,customer,status,priority,order_date,requested_delivery_date,total_order_quantity",
 "ORDERBYDESCsys_created_on"
 ),
 fetchTable(
 "x_2056099_indust_0_production_order",
 "number,status,finished_product,quantity_planned,quantity_produced,quantity_remaining,priority,planned_start_date,planned_end_date,assigned_resource"
 ),
 fetchTable(
 "x_2056099_indust_0_prod_res",
 "resource_name,resource_type,status,maintenance_required,capacity_per_day"
 ),
 fetchTable(
 "x_2056099_indust_0_inv_stock",
 "material_product,total_quantity,available_quantity,reserved_quantity,safety_stock,reorder_level,status,location"
 ),
 fetchTable(
 "x_2056099_indust_0_inv_alert",
 "number,alert_type,severity,alert_message,status,material_product,inventory_stock",
 "status!=resolved"
 ),
 ]);
 setOrders(o);
 setProdOrders(p);
 setResources(r);
 setStock(s);
 setAlerts(a);
 } catch (err) {
 console.error("Dashboard fetch error:", err);
 } finally {
 setLoading(false);
 }
 }

 /* ── Computed KPIs ── */
 const now = new Date();
 const sevenDays = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);

 const isActive = (r: Rec) => {
 const s = val(r.status).toLowerCase();
 return s !== "completed" && s !== "cancelled" && s !== "closed" && s !== "complete";
 };

 const totalOrders = orders.length;
 const activeOrders = orders.filter(isActive).length;

 const inProduction = prodOrders.filter(
 (p) => val(p.status).toLowerCase() === "in_progress" || val(p.status).toLowerCase() === "in progress"
 ).length;
 const completedProd = prodOrders.filter(
 (p) => val(p.status).toLowerCase() === "completed" || val(p.status).toLowerCase() === "complete"
 ).length;

 const overdue = orders.filter((o) => {
 const d = val(o.requested_delivery_date);
 return d && new Date(d) < now && isActive(o);
 }).length;

 const upcoming = orders.filter((o) => {
 const d = val(o.requested_delivery_date);
 return d && new Date(d) >= now && new Date(d) <= sevenDays && isActive(o);
 }).length;

 /* Resources */
 const resByStatus = (s: string) => resources.filter((r) => val(r.status).toLowerCase() === s).length;
 const activeProd = prodOrders.filter(isActive).length;
 const plannedProd = prodOrders.filter(
 (p) => val(p.status).toLowerCase() === "planned" || val(p.status).toLowerCase() === "new"
 ).length;

 /* Stock */
 const totalAvailQty = stock.reduce((s, r) => s + num(r.available_quantity), 0);
 const totalReservedQty = stock.reduce((s, r) => s + num(r.reserved_quantity), 0);
 const lowStockCount = stock.filter((r) => {
 const avail = num(r.available_quantity);
 const safety = num(r.safety_stock);
 return safety > 0 && avail <= safety;
 }).length;

 /* Alerts by severity */
 const sevMatch = (a: Rec, sev: string[]) => {
 const v = val(a.severity).toLowerCase();
 return sev.includes(v);
 };
 const criticalAlerts = alerts.filter((a) => sevMatch(a, ["critical", "1"]));
 const highAlerts = alerts.filter((a) => sevMatch(a, ["high", "2"]));
 const mediumAlerts = alerts.filter((a) => sevMatch(a, ["medium", "3"]));
 const lowAlerts = alerts.filter(
 (a) => !sevMatch(a, ["critical", "1", "high", "2", "medium", "3"])
 );

 /* Deadline helper */
 function deadlineStatus(o: Rec) {
 if (!isActive(o)) return "done";
 const d = val(o.requested_delivery_date);
 if (!d) return "none";
 const dt = new Date(d);
 if (dt < now) return "overdue";
 if (dt <= sevenDays) return "upcoming";
 return "on-track";
 }

 const deadlineLabel: Record<string, string> = {
 overdue: "⚠ Overdue",
 upcoming: "⏰ Due Soon",
 "on-track": "✓ On Track",
 done: "✓ Done",
 none: "—",
 };

 if (loading) {
 return (
 <div className="ops-loading">
 <div className="ops-spinner" />
 <p>Loading dashboard data…</p>
 </div>
 );
 }

 return (
 <div className="ops-dashboard">
 {/* ── Header ── */}
 <header className="ops-header">
 <h1>Industrial Operations Dashboard</h1>
 <p className="ops-subtitle">Real-time overview of production, inventory, and order operations</p>
 </header>

 {/* ── KPI Overview ── */}
 <section className="ops-section">
 <h2 className="ops-section-title">KPI Overview</h2>
 <div className="ops-kpi-grid">
 <KpiCard label="Total Orders" value={totalOrders} icon="📋" />
 <KpiCard label="Active Orders" value={activeOrders} icon="🔄" accent="blue" />
 <KpiCard label="In Production" value={inProduction} icon="⚙️" accent="amber" />
 <KpiCard label="Completed" value={completedProd} icon="✅" accent="green" />
 <KpiCard label="Overdue" value={overdue} icon="⚠️" accent="red" />
 <KpiCard label="Upcoming Deadlines" value={upcoming} icon="📅" accent="orange" />
 </div>
 </section>

 {/* ── Production & Machines ── */}
 <section className="ops-section">
 <h2 className="ops-section-title">Production &amp; Machines</h2>
 <div className="ops-two-col">
 <div className="ops-card">
 <h3>Resource Status</h3>
 <div className="ops-resource-grid">
 <ResourceBar label="Available" count={resByStatus("available")} total={resources.length} color="#2e7d32" />
 <ResourceBar label="Busy" count={resByStatus("busy")} total={resources.length} color="#f9a825" />
 <ResourceBar label="Maintenance" count={resByStatus("maintenance")} total={resources.length} color="#e65100" />
 <ResourceBar label="Unavailable" count={resByStatus("unavailable")} total={resources.length} color="#c62828" />
 </div>
 <p className="ops-resource-total">Total Resources: {resources.length}</p>
 </div>
 <div className="ops-card">
 <h3>Active Production</h3>
 <div className="ops-big-number">{activeProd}</div>
 <p className="ops-big-label">production orders currently active</p>
 <div className="ops-prod-breakdown">
 <span className="ops-prod-stat">In Progress: {inProduction}</span>
 <span className="ops-prod-stat">Planned: {plannedProd}</span>
 </div>
 </div>
 </div>
 </section>

 {/* ── Customer Orders & Deadlines ── */}
 <section className="ops-section">
 <h2 className="ops-section-title">Customer Orders &amp; Deadlines</h2>
 <div className="ops-card ops-card--full">
 {orders.length === 0 ? (
 <p className="ops-empty">No customer orders found.</p>
 ) : (
 <div className="ops-table-wrap">
 <table className="ops-table">
 <thead>
 <tr>
 <th>Order #</th>
 <th>Customer</th>
 <th>Status</th>
 <th>Priority</th>
 <th>Order Date</th>
 <th>Deadline</th>
 <th>Qty</th>
 <th>Deadline Status</th>
 </tr>
 </thead>
 <tbody>
 {orders.slice(0, 25).map((o, i) => {
 const ds = deadlineStatus(o);
 return (
 <tr key={i}>
 <td className="ops-mono">{dv(o.number) || "—"}</td>
 <td>{dv(o.customer) || "—"}</td>
 <td>
 <span className={`ops-badge ops-badge--${val(o.status).toLowerCase().replace(/\s+/g, "-")}`}>
 {dv(o.status) || "—"}
 </span>
 </td>
 <td>{dv(o.priority) || "—"}</td>
 <td>{dv(o.order_date) || "—"}</td>
 <td>{dv(o.requested_delivery_date) || "—"}</td>
 <td className="ops-right">{dv(o.total_order_quantity) || "0"}</td>
 <td>
 <span className={`ops-deadline ops-deadline--${ds}`}>{deadlineLabel[ds] || "—"}</span>
 </td>
 </tr>
 );
 })}
 </tbody>
 </table>
 </div>
 )}
 </div>
 </section>

 {/* ── Inventory Overview ── */}
 <section className="ops-section">
 <h2 className="ops-section-title">Inventory Overview</h2>
 <div className="ops-kpi-grid ops-kpi-grid--5">
 <KpiCard label="Total Items" value={stock.length} icon="📦" />
 <KpiCard label="Available Qty" value={totalAvailQty} icon="✅" accent="green" />
 <KpiCard label="Reserved Qty" value={totalReservedQty} icon="🔒" accent="blue" />
 <KpiCard label="Low Stock Items" value={lowStockCount} icon="⚠️" accent={lowStockCount > 0 ? "red" : "green"} />
 <KpiCard label="Active Alerts" value={alerts.length} icon="🔔" accent={alerts.length > 0 ? "orange" : "green"} />
 </div>
 </section>

 {/* ── Procurement Overview ── */}
 <section className="ops-section">
 <h2 className="ops-section-title">Procurement Overview</h2>
 <Placeholder icon="🏭" text="Procurement tracking will appear here when procurement data is available." />
 </section>

 {/* ── Supplier Tracking ── */}
 <section className="ops-section">
 <h2 className="ops-section-title">Supplier Tracking</h2>
 <Placeholder icon="🚚" text="Supplier tracking will appear here when supplier data is available." />
 </section>

 {/* ── Alerts & Exceptions ── */}
 <section className="ops-section">
 <h2 className="ops-section-title">Alerts &amp; Exceptions</h2>
 <div className="ops-card ops-card--full">
 {alerts.length === 0 ? (
 <p className="ops-empty">No active alerts. All systems operating normally.</p>
 ) : (
 <div className="ops-alerts-list">
 {criticalAlerts.length > 0 && <AlertGroup label="Critical" severity="critical" alerts={criticalAlerts} />}
 {highAlerts.length > 0 && <AlertGroup label="High" severity="high" alerts={highAlerts} />}
 {mediumAlerts.length > 0 && <AlertGroup label="Medium" severity="medium" alerts={mediumAlerts} />}
 {lowAlerts.length > 0 && <AlertGroup label="Low / Info" severity="low" alerts={lowAlerts} />}
 </div>
 )}
 </div>
 </section>

 {/* ── Demand Forecasting ── */}
 <section className="ops-section">
 <h2 className="ops-section-title">Demand Forecasting</h2>
 <Placeholder icon="📈" text="Demand forecasting integration pending." />
 </section>

 {/* ── Digital Twin ── */}
 <section className="ops-section">
 <h2 className="ops-section-title">Digital Twin</h2>
 <Placeholder icon="🔬" text="Production simulation and what-if analysis will be integrated here in a future update." />
 </section>

 <footer className="ops-footer">
 <p>Industrial Operations Dashboard — Data refreshed on load</p>
 </footer>
 </div>
 );
}
